import { defineArgvCatalog, defineArgvHelpPresentation, parseStandardArgv, type ArgvOptionDefinition, type StandardArgvAction, type StandardArgvPolicy, HELP_EARLY_EXIT_OPTIONS, stopArgvAtFirstEarlyExit, formatArgvOptionHelp, formatArgvUsageSummary } from '@/features/wesh/argv-v2';
import { writeCommandUsageError } from '@/features/wesh/commands/_shared/usage-output';
import { writeCommandHelp } from '@/features/wesh/commands/_shared/usage-output';
import { stripLeadingCLocaleWhitespace } from '@/features/wesh/commands/_shared/numeric-whitespace';
import type { WeshCommandImplementation, WeshCommandResult, WeshCommandContext } from '@/features/wesh/types';

const sleepHelpOption = {
  semantic: { kind: 'effects', effects: [{ key: 'help', value: true }] },
  forms: [{ kind: 'long', name: 'help', value: { kind: 'none' } }],
} as const satisfies ArgvOptionDefinition<StandardArgvAction<never>>;
const sleepArgvCatalog = defineArgvCatalog<StandardArgvAction<never>>({ nonExecutableLongOptions: ['version'], definitions: [sleepHelpOption] });
const sleepArgvHelp = defineArgvHelpPresentation({
  catalog: sleepArgvCatalog,
  rows: [{ forms: sleepHelpOption.forms, summary: 'display this help and exit', category: 'common' }],
});
const sleepArgvPolicy: StandardArgvPolicy = {
  longNameMatch: 'unique-prefix',
  optionBoundary: 'continue',
  occurrenceRetention: 'none',
};

function parseHexadecimalFloat({
  value,
}: {
  value: string,
}): number {
  const sign = value.startsWith('-') ? -1 : 1;
  const unsigned = value.replace(/^[+-]/u, '').slice(2);
  const [mantissaText, exponentText] = unsigned.split(/[pP]/u, 2);
  const [integerText = '', fractionText = ''] = mantissaText!.split('.', 2);
  let magnitude = integerText.length === 0 ? 0 : Number.parseInt(integerText, 16);
  for (let index = 0; index < fractionText.length; index += 1) {
    magnitude += Number.parseInt(fractionText[index]!, 16) / (16 ** (index + 1));
  }
  if (magnitude === 0) {
    return sign * 0;
  }
  return sign * magnitude * (2 ** Number(exponentText ?? 0));
}

function isNegativeNonzeroNumericOperand({
  value,
}: {
  value: string,
}): boolean {
  if (!value.startsWith('-')) {
    return false;
  }

  const unsigned = value.slice(1);
  if (/^0[xX]/u.test(unsigned)) {
    const [mantissa = ''] = unsigned.slice(2).split(/[pP]/u, 1);
    return /[1-9a-fA-F]/u.test(mantissa);
  }

  const [significand = ''] = unsigned.split(/[eE]/u, 1);
  return /[1-9]/u.test(significand);
}

function parseSleepOperand({
  value,
}: {
  value: string,
}): { ok: true, seconds: number } | { ok: false } {
  const numericText = stripLeadingCLocaleWhitespace({ value });
  const infinitySuffix = (() => {
    const finalCharacter = numericText.at(-1);
    switch (finalCharacter) {
    case 's':
    case 'm':
    case 'h':
    case 'd':
      return finalCharacter;
    case undefined:
      return '';
    default:
      return '';
    }
  })();
  const infinityOperand = (() => {
    switch (infinitySuffix) {
    case '':
      return numericText;
    case 's':
    case 'm':
    case 'h':
    case 'd':
      return numericText.slice(0, -1);
    default: {
      const _ex: never = infinitySuffix;
      throw new Error(`Unhandled sleep suffix: ${_ex}`);
    }
    }
  })();
  if (/^\+?(?:inf|infinity)$/iu.test(infinityOperand)) {
    return { ok: true, seconds: Number.POSITIVE_INFINITY };
  }

  const match = numericText.match(/^([+-]?(?:(?:0[xX](?:[0-9a-fA-F]+(?:\.[0-9a-fA-F]*)?|\.[0-9a-fA-F]+)(?:[pP][+-]?[0-9]+)?)|(?:(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?)))([smhd]?)$/u);
  if (match === null) {
    return { ok: false };
  }

  const numericOperand = match[1] ?? '';
  const amount = /^[+-]?0[xX]/u.test(numericOperand)
    ? parseHexadecimalFloat({ value: numericOperand })
    : Number.parseFloat(numericOperand);
  if (
    Number.isNaN(amount)
    || amount < 0
    || (amount === 0 && isNegativeNonzeroNumericOperand({ value: numericOperand }))
  ) {
    return { ok: false };
  }

  const multiplier = (() => {
    switch (match[2] ?? '') {
    case '':
    case 's':
      return 1;
    case 'm':
      return 60;
    case 'h':
      return 60 * 60;
    case 'd':
      return 60 * 60 * 24;
    default:
      return undefined;
    }
  })();

  if (multiplier === undefined) {
    return { ok: false };
  }

  return {
    ok: true,
    seconds: amount * multiplier,
  };
}

export const sleepCommandImplementation: WeshCommandImplementation = {
  fn: async ({ context }: { context: WeshCommandContext }): Promise<WeshCommandResult> => {
    const parsed = parseStandardArgv({
      args: stopArgvAtFirstEarlyExit({
        args: context.args,
        catalog: sleepArgvCatalog,
        policy: sleepArgvPolicy,
        earlyExitOptions: HELP_EARLY_EXIT_OPTIONS,
      }),
      catalog: sleepArgvCatalog,
      policy: sleepArgvPolicy,
    });

    const diagnostic = parsed.diagnostics[0];
    if (diagnostic !== undefined) {
      await writeCommandUsageError({
        context,
        command: 'sleep',
        message: `sleep: ${diagnostic.message}`,
        usageSummary: formatArgvUsageSummary({ presentation: sleepArgvHelp }),
      });
      return { exitCode: 1 };
    }

    if (parsed.optionValues.help === true) {
      await writeCommandHelp({
        context,
        command: 'sleep',
        optionLines: formatArgvOptionHelp({ presentation: sleepArgvHelp }),
      });
      return { exitCode: 0 };
    }

    if (parsed.positionals.length === 0) {
      await writeCommandUsageError({
        context,
        command: 'sleep',
        message: 'sleep: missing operand',
        usageSummary: formatArgvUsageSummary({ presentation: sleepArgvHelp }),
      });
      return { exitCode: 1 };
    }

    let seconds = 0;
    for (const operand of parsed.positionals) {
      const parsedOperand = parseSleepOperand({
        value: operand,
      });
      if (!parsedOperand.ok) {
        await writeCommandUsageError({
          context,
          command: 'sleep',
          message: `sleep: invalid time interval '${operand}'`,
          usageSummary: formatArgvUsageSummary({ presentation: sleepArgvHelp }),
        });
        return { exitCode: 1 };
      }
      seconds += parsedOperand.seconds;
    }

    const waitStatus = await context.process.waitForSignalOrTimeout({
      timeoutMs: seconds * 1000,
    });
    if (waitStatus !== undefined) {
      return {
        exitCode: 0,
        waitStatus,
      };
    }

    return { exitCode: 0 };
  },
};

